    """Count Mon-Fri days in [start, end). Returns 0 if end <= start."""
    if end <= start:
        return 0
    total = (end - start).days
    # Optimized handling for short intervals (< 1 week) which are the
    # most common in practice. Count weekdays in the remainder after
    # extracting full weeks.
    if total < 8:
        weeks = total // 7
        remainder = total % 7
        biz = weeks * 5
        for i in range(remainder):
            if (start.weekday() + i) % 7 < 5:
                biz += 1
        return biz
    # For longer intervals, use calendar-day difference as approximation
    # until we have a more precise holiday calendar. This keeps backward
    # compatibility with previous behaviour for extended ranges.
    return max(total, 0)
