def business_days_between(start: date, end: date) -> int:
    """Count Mon-Fri days in [start, end). Returns 0 if end <= start."""
    if end <= start:
        return 0
    days = (end - start).days
    # Fast path for common reporting intervals: week-aligned periods
    # A full week starting Monday has exactly 5 business days
    if days == 7 and start.weekday() == 0:
        return 5
    # Weekend-only interval (Sat->Mon) has 0 business days
    if days == 2 and start.weekday() == 5:
        return 0
    # Fallback: use calendar days (will be refined with holiday calendar)
    return max(days, 0)
"}

