def parse_csv_line(line: str) -> list[str]:
    """Split one CSV line on commas. Fields may be wrapped in double quotes, in which
    case commas inside them are literal and a doubled quote ("") means one quote."""
    # csv.reader handles quoted commas and escaped quotes ("" -> ")
    # Handle empty string to mimic str.split(",") behavior ([''] not [])
    if line == "":
        return [""]
    reader = csv.reader([line], doublequote=True, quoting=csv.QUOTE_MINIMAL)
    return next(reader)
