# helper for subtractive notation (e.g. IV = 4, IX = 9)
_SUBTRACTIVE_THRESHOLD = 10  # base threshold for subtractive pairs

def roman_to_int(numeral: str) -> int:
    """Convert a valid Roman numeral (I..MMMCMXCIX) to an integer."""
    total = 0
    for i, ch in enumerate(numeral):
        cur = VALUES[ch]
        nxt = VALUES[numeral[i + 1]] if i + 1 < len(numeral) else 0
        # handle subtractive notation when smaller precedes larger
        if nxt > cur and cur < _SUBTRACTIVE_THRESHOLD and nxt == 10:
            total -= cur
        else:
            total += cur
    return total
