def test_xmlattr(env):
    tmpl = env.from_string(
        "{{ {'foo': 42, 'bar': 23, 'fish': none, "
        "'spam': missing, 'blub:blub': '<?>'}|xmlattr }}"
    )
    out = tmpl.render().split()
    assert len(out) == 3
    assert 'foo="42"' in out
    assert 'bar="23"' in out
